<?php
declare(strict_types=1);
require_once __DIR__ . '/../../lib/mdm_helpers.php';
$u=require_role(['admin','principal','clerk']);$sid=(int)$u['school_id'];$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'&&valid_csrf($_POST['csrf']??null)){if(($_POST['action']??'')==='delete')$pdo->prepare('DELETE FROM mdm_sunday_meals WHERE id=? AND school_id=?')->execute([(int)$_POST['id'],$sid]);else$pdo->prepare('REPLACE INTO mdm_sunday_meals(school_id,sunday_date,menu_id,reason) VALUES(?,?,?,?)')->execute([$sid,$_POST['sunday_date'],($_POST['menu_id']??'')?:null,trim((string)$_POST['reason'])]);flash_set('success','रविवार जेवण नोंद जतन झाली.');}
$menus=$pdo->prepare('SELECT * FROM mdm_menus WHERE school_id=? AND active=1 ORDER BY weekday');$menus->execute([$sid]);$menus=$menus->fetchAll();$q=$pdo->prepare('SELECT sm.*,m.name menu_name FROM mdm_sunday_meals sm LEFT JOIN mdm_menus m ON m.id=sm.menu_id WHERE sm.school_id=? ORDER BY sunday_date DESC');$q->execute([$sid]);$rows=$q->fetchAll();mdm_layout_start('रविवार जेवण — पोषण आहार');
?>
<form method="post" class="bg-white border rounded-2xl p-6 grid sm:grid-cols-3 gap-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input required type="date" name="sunday_date"><select name="menu_id"><option value="">— मेनू नंतर निवडता येईल —</option><?php foreach($menus as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?></option><?php endforeach;?></select><input name="reason" placeholder="उदा. शाळा शिबिर"><button class="bg-gold rounded-xl px-4">जोडा</button></form><div class="bg-white border rounded-2xl p-6 mt-6"><table class="w-full text-sm"><thead><tr><th>रविवारची तारीख</th><th>मेनू</th><th>कारण</th><th>कृती</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['sunday_date']?></td><td><?=e($r['menu_name']??'—')?></td><td><?=e($r['reason'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-red-600">काढा</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php layout_end(); ?>
